+// DeriveCTAURLFields returns the CTA url fields a component's input_schema
+// declares: every field whose name ends "_url" AND which has a sibling
+// "<stem>_label" or "<stem>_text" field in the same schema.
+//
+// The sibling test is load-bearing, not cosmetic: site_assets.image and
+// site_assets.logo fields also end in "_url" (32 of them across the live
+// library) and must never be touched by link resolution. A destination that
+// has no label is not a button; a label with no destination is the defect
+// this pairing exists to make expressible.
+type CTAField struct {
+	URLField   string // "cta_primary_url"
+	LabelField string // "cta_primary_label"
+	Source     string // declared source, so callers can reason about authority
+}
+
+func DeriveCTAURLFields(inputSchema map[string]interface{}) []CTAField {
+	fields, _ := inputSchema["fields"].(map[string]interface{})
+	if len(fields) == 0 {
+		return nil
+	}
+	stems := make(map[string]string, len(fields)) // stem -> label field name
+	for name := range fields {
+		for _, suf := range []string{"_label", "_text"} {
+			if strings.HasSuffix(name, suf) {
+				stems[strings.TrimSuffix(name, suf)] = name
+			}
+		}
+	}
+	var out []CTAField
+	for name, raw := range fields {
+		if !strings.HasSuffix(name, "_url") {
+			continue
+		}
+		label, ok := stems[strings.TrimSuffix(name, "_url")]
+		if !ok {
+			continue
+		}
+		spec, _ := raw.(map[string]interface{})
+		src, _ := spec["source"].(string)
+		out = append(out, CTAField{URLField: name, LabelField: label, Source: src})
+	}
+	sort.Slice(out, func(i, j int) bool { return out[i].URLField < out[j].URLField })
+	return out
+}

+func TestDeriveCTAURLFields(t *testing.T) {
+	// image/logo url fields have no sibling label and must NOT be returned
+	schema := map[string]interface{}{"fields": map[string]interface{}{
+		"cta_primary_url":   map[string]interface{}{"source": "site_specs.cta.primary_url"},
+		"cta_primary_label": map[string]interface{}{"source": "static"},
+		"guide_image_url":   map[string]interface{}{"source": "site_assets.image"},
+		"guide_image_alt":   map[string]interface{}{"source": "llm"},
+	}}
+	got := DeriveCTAURLFields(schema)
+	if len(got) != 1 || got[0].URLField != "cta_primary_url" {
+		t.Fatalf("want only cta_primary_url, got %+v", got)
+	}
+	if got[0].LabelField != "cta_primary_label" || got[0].Source != "site_specs.cta.primary_url" {
+		t.Fatalf("pairing/source wrong: %+v", got[0])
+	}
+}
